  composite_pins(signature, acl, config, definer, volatility, language_name, result_type, strict_function) as (values
    ('private.review_receipt(private.agreement_reviews,boolean)','{postgres=X/postgres}','{search_path=pg_catalog}',false,'s','plpgsql','jsonb',false),
    ('private.closure_erasure_assert_current_v5(private.closure_executions_v5)','{postgres=X/postgres}','{search_path=pg_catalog}',true,'v','plpgsql','void',false),
    ('private.closure_erasure_refresh_steps_v5(private.closure_executions_v5)','{postgres=X/postgres}','{search_path=pg_catalog}',true,'v','plpgsql','void',false)
  ),
  ready_function as (
    select p.oid, p.prosrc, pg_get_functiondef(p.oid) as definition
    from pg_proc p where p.oid = to_regprocedure('private.retention_ai_source_ready()')
  ),
  cert as (
    select (select count(*) from private.closure_source_v5) as source_rows,
           (select count(*) from private.closure_erasure_source_v5) as erasure_rows,
           (select sha256 from private.closure_source_v5 where singleton) as old_source,
           (select sha256 from private.closure_erasure_source_v5 where singleton) as erasure_sha,
           private.closure_source_digest_v5() as live_digest,
           private.retention_ai_source_ready() as ready,
           private.closure_erasure_binding_v5()->>'sourceSha256' as bound
  ),
  problems as (
    select 'METADATA_DRIFT' as kind, pin.signature as detail
    from metadata_pins pin
    where (select md5(((to_jsonb(p)-'oid'-'pronamespace'-'proowner'-'prolang'-'proacl'-'prosrc')
        ||jsonb_build_object('namespace',n.nspname,'owner',pg_get_userbyid(p.proowner),'language',l.lanname,'acl',p.proacl::text))::text)
        from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang
        where p.oid=to_regprocedure(pin.signature)) is distinct from pin.metadata_md5
    union all
    select 'BODY_DRIFT', pin.signature
    from body_pins pin
    where (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid=to_regprocedure(pin.signature)) is distinct from pin.body_md5
    union all
    select 'COMPOSITE_METADATA_DRIFT', pin.signature
    from composite_pins pin
    where not exists(select 1 from pg_proc p where p.oid=to_regprocedure(pin.signature) and p.proowner='postgres'::regrole and p.proacl::text=pin.acl and coalesce(p.proconfig::text,'')=pin.config and p.prosecdef=pin.definer and p.provolatile::text=pin.volatility
      and p.proisstrict=pin.strict_function and p.prolang=(select oid from pg_language where lanname=pin.language_name) and p.prorettype=to_regtype(pin.result_type) and p.prokind='f')
    union all
    select 'RETENTION_CLASS_DRIFT', 'the description of the retention class AGREEMENT_REVIEWS is not the predecessor text'
    where (select description from private.retention_data_classes where code='AGREEMENT_REVIEWS' and required and active) is distinct from 'Immutable bilateral completed-Agreement reviews and their account-level reputation projection (private.agreement_reviews).'
    union all
    select 'CLOSURE_IN_FLIGHT', 'a closure execution is EXECUTING'
    where exists(select 1 from private.closure_executions_v5 where state='EXECUTING')
    union all
    select 'CERTIFICATE_CARDINALITY', 'closure_source_v5 and closure_erasure_source_v5 must hold exactly one row each'
    from cert where source_rows<>1 or erasure_rows<>1
    union all
    select 'CERTIFICATE_NOT_READY', 'the certificate, the live digest, the erasure source row, the readiness and the binding must all agree'
    from cert where old_source is null or old_source is distinct from live_digest or old_source is distinct from erasure_sha
      or ready is distinct from true or bound is distinct from old_source
    union all
    select 'READINESS_PREDECESSOR_DRIFT', 'retention_ai_source_ready() is not the certified predecessor'
    where not exists(select 1 from ready_function r, cert c
      where (length(r.prosrc)-length(replace(r.prosrc,c.old_source,'')))=length(c.old_source)
        and md5(replace(replace(r.prosrc,E'\r\n',E'\n'),c.old_source,'__CERTIFIED_SOURCE__'))='bc85a1a744869abb6441e647b18b2195')
    union all
    select 'READINESS_LITERAL_DRIFT', 'the readiness definition must carry exactly one certified literal'
    from ready_function r, cert c
    where (length(r.definition)-length(replace(r.definition,c.old_source,'')))<>length(c.old_source)
      or (select count(*) from regexp_matches(r.definition,'[0-9a-f]{64}','g'))<>1
    union all
    select 'D12_ALREADY_PRESENT', 'a D12 object already exists'
    where to_regclass('private.agreement_review_comments_v1') is not null
      or exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname,p.proname) in(('private','guard_review_comment_mutation'),('private','review_comment_input_v1'),('public','rpc_submit_agreement_review_v2'),('public','rpc_get_my_agreement_review_v2'),('public','rpc_list_review_comments_v1'),('public','rpc_moderate_review_comment_service_v1')))
      or exists(select 1 from pg_trigger where tgname in('agreement_review_comment_closure_guard_v1','agreement_review_comment_mutation_guard_v1'))
      or exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in('agreement_review_comments_v1_author_idx','agreement_review_comments_v1_pkey','agreement_review_comments_v1_target_idx'))
    union all
    select 'ROSTER_OR_CATALOG_DRIFT', 'the redaction roster, the AGREEMENT_REVIEWS catalog row, the export catalog or the export projection is not the expected predecessor'
    where cardinality(private.closure_redaction_relations_v5())<>75
      or (private.closure_redaction_relations_v5())[75] is distinct from 'public.app_accounts'
      or 'private.agreement_reviews'=any(private.closure_redaction_relations_v5())
      or (select relations from private.closure_dataset_catalog_v5 where data_class='AGREEMENT_REVIEWS') is distinct from array['private.agreement_reviews']::text[]
      or jsonb_array_length(private.data_export_dataset_catalog())<>52
      or (select v->'fields' from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'key'='ownAgreementReviews') is distinct from '["agreementId","createdAt","id","rating","tags"]'::jsonb
      or private.data_export_projection_sha_v5() is distinct from '70009062e365b92295eba138a63868e84fd712ee270d9e6ea24237507e5eecfa'
    union all
    select 'STAR_TABLE_DRIFT', 'private.agreement_reviews is not the expected immutable star table'
    where (select string_agg(attname::text||':'||format_type(atttypid,atttypmod)||':'||attnotnull::text||':'||attidentity::text||':'||attgenerated::text,',' order by attnum)
           from pg_attribute where attrelid='private.agreement_reviews'::regclass and attnum>0 and not attisdropped) is distinct from 'id:uuid:true::,agreement_id:uuid:true::,reviewer_account_id:uuid:true::,target_account_id:uuid:true::,rating:integer:true::,tags:text[]:true::,client_request_id:uuid:true::,input_hash:text:true::,created_at:timestamp with time zone:true::'
      or (select md5(string_agg(conname||':'||replace(pg_get_constraintdef(oid),'REFERENCES public.','REFERENCES '),';' order by conname)) from pg_constraint where conrelid='private.agreement_reviews'::regclass) is distinct from 'fe44059a7fa96aeb732ff3459f6865d1'
      or (select string_agg(tgname,',' order by tgname) from pg_trigger where tgrelid='private.agreement_reviews'::regclass and not tgisinternal) is distinct from 'pre_v3_closure_review,pre_v3_review_immutable'
      or (select relacl::text from pg_class where oid='private.agreement_reviews'::regclass) is distinct from '{postgres=arwdDxtm/postgres}'
      or not (select relrowsecurity and relforcerowsecurity from pg_class where oid='private.agreement_reviews'::regclass)
      or (select count(*) from pg_policy where polrelid='private.agreement_reviews'::regclass)<>0
  )
select jsonb_build_object(
  'unit', 'D12_DEV_PREFLIGHT',
  'metadataPinsChecked', (select count(*) from metadata_pins),
  'bodyPinsChecked', (select count(*) from body_pins),
  'problems', coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'detail',detail) order by kind,detail) from problems), '[]'::jsonb),
  'certifiedSource', (select old_source from cert),
  'certifiedSourceIsTheRecordedDevOne', (select old_source is not distinct from '58447d7730e909a0c0e60dd92ef77416af927471bd6f645988448e32c6e3cb46' from cert),
  'liveDigest', (select live_digest from cert),
  'ready', (select ready from cert),
  'erasureBindingMatches', (select bound is not distinct from old_source from cert),
  'closureExecutionsExecuting', (select count(*) from private.closure_executions_v5 where state='EXECUTING'),
  'closureExecutionsTotal', (select count(*) from private.closure_executions_v5),
  'redactionRelations', cardinality(private.closure_redaction_relations_v5()),
  'exportDatasets', jsonb_array_length(private.data_export_dataset_catalog()),
  'exportProjectionSha', private.data_export_projection_sha_v5(),
  'requiredRetentionClasses', (select count(*) from private.retention_data_classes where required and active),
  'reviews', (select count(*) from private.agreement_reviews),
  'reviewIdHashBaseline', (select md5(string_agg(id::text||':'||input_hash,',' order by id)) from private.agreement_reviews),
  'ledgerRows', (select count(*) from supabase_migrations.schema_migrations),
  'latestLedgerVersion', (select max(version) from supabase_migrations.schema_migrations),
  'serverVersion', current_setting('server_version'),
  'checkedAt', to_char(clock_timestamp() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
) as preflight;
